440	// mergeRecord applies the single dedup/conflict rule shared by both submit
441	// phases (records within the batch, and the batch against stored history): a
442	// record's identity is its node id and seq together, and known must contain
443	// only records of that same node. If known already holds the identity, the
444	// incoming record is a duplicate when Heartbeat.Equal says the content is
445	// identical — collection time compared as an instant, node id and version
446	// compared as-is — and a conflict when any field differs. A conflict is an
447	// error naming the node and seq and changes nothing; a duplicate leaves
448	// known untouched and reports dup. Otherwise the record is appended and
449	// returned in the updated slice.
450	func mergeRecord(known []Heartbeat, r Heartbeat) (updated []Heartbeat, dup bool, err error) {
451		for _, e := range known {
452			if e.Seq == r.Seq {
453				if !e.Equal(r) {
454					return nil, false, fmt.Errorf("conflicting record for node %q seq %d: content differs", r.NodeID, r.Seq)
455				}
456				return known, true, nil
457			}
458		}
459		return append(known, r), false, nil
460	}
461	
462	// Submit persists a batch of heartbeats. The whole batch is validated and
463	// checked for duplicates/conflicts against stored data (and within the batch)
464	// before anything is written: a single invalid or conflicting record fails
465	// the batch with no changes. Duplicates are counted, not written. A
466	// successful return means the batch was durably persisted; a persistence
467	// failure is reported and previously queryable data is left intact.
468	func (s *Store) Submit(records []Heartbeat, receiveTime time.Time) (newCount, dupCount int, err error) {
469		if len(records) == 0 {
470			return 0, 0, fmt.Errorf("no heartbeat records provided")
471		}
472		for _, r := range records {
473			if err := ValidateHeartbeat(r, receiveTime); err != nil {
474				return 0, 0, fmt.Errorf("invalid heartbeat for node %q seq %d: %w", r.NodeID, r.Seq, err)
475			}
476		}
477	
478		unlock, err := s.lock(true)
479		if err != nil {
480			return 0, 0, err
481		}
482		defer unlock()
483	
484		// Deduplicate within the batch: same node+seq with equal content counts
485		// as a duplicate; same node+seq with differing content is a conflict.
486		merged := make(map[string][]Heartbeat)
487		for _, r := range records {
488			list, dup, err := mergeRecord(merged[r.NodeID], r)
489			if err != nil {
490				return 0, 0, err
491			}
492			if dup {
493				dupCount++
494				continue
495			}
496			merged[r.NodeID] = list
497		}
498	
499		// Merge with stored data per node, collecting new file contents.
500		type update struct {
501			loc     nodeLocation
502			records []Heartbeat
503		}
504		var updates []update
505		for nodeID, batch := range merged {
506			loc := s.nodeLocationFor(nodeID)
507			nf, err := loadNodeFile(loc)
508			if err != nil {
509				return 0, 0, err
510			}
511			existing := []Heartbeat{}
512			if nf != nil {
513				existing = nf.Records
514			}
515			for _, r := range batch {
516				var dup bool
517				existing, dup, err = mergeRecord(existing, r)
518				if err != nil {
519					return 0, 0, err
520				}
521				if dup {
522					dupCount++
523				} else {
524					newCount++
525				}
526			}
527			sort.Slice(existing, func(i, j int) bool { return existing[i].Seq < existing[j].Seq })
528			updates = append(updates, update{loc: loc, records: existing})
529		}
530	
531		// Persist. All updates are appends to previously verified data, so a
532		// failure here leaves every previously queryable record intact.
533		for _, u := range updates {
534			if err := writeNodeFile(u.loc.path, u.records); err != nil {
535				return 0, 0, fmt.Errorf("failed to persist heartbeat batch: %w", err)
536			}
537		}
538		return newCount, dupCount, nil
539	}
540	
541	// HealthResult is the health judgement for one node based on real telemetry.
542	type HealthResult struct {
543		NodeID      string
544		Status      string // "online", "offline", "notelemetry"
545		Seq         int64
546		CollectedAt time.Time
547		Version     string
548		Height      int64
549		Missed      int64 // cumulative missed duties at the latest heartbeat
550		Findings    []string
551	
552		// Baseline-relative missed duties, populated only by HealthSince.
553		// BaselineSeq is the seq of the heartbeat the query was anchored to;
554		// BaselineMissed is the cumulative count at that heartbeat. When
555		// NewMissedKnown is false the cumulative counter went backwards
556		// somewhere between the baseline and the latest record, so the number of
557		// newly missed duties cannot be derived; Findings then reports the
558		// rollback. Missed always remains the latest cumulative count.
559		BaselineSeq    int64
560		BaselineMissed int64
561		NewMissed      int64
562		NewMissedKnown bool
563	}
564	
565	// rollbackFinding warns that the cumulative missed-duty counter decreased
566	// between two adjacent saved heartbeats (typically a node counter reset),
567	// which makes the endpoint difference unusable as the new-miss count.
568	const rollbackFinding = "累计漏签数回退"
569	
570	// Health judges a node from its latest telemetry (the record with the
571	// greatest seq). A node with no heartbeats returns Status "notelemetry". A
572	// query time earlier than the record's collection time is an error. Online
573	// status uses collection age against the query time: at most 60s is online
574	// (exactly 60s still online). Version skew and missed-duty rules follow the
575	// existing Evaluate rules.
576	func (s *Store) Health(nodeID string, at time.Time, expectedVersion string, toleratedMisses int) (HealthResult, error) {
577		return s.health(nodeID, at, expectedVersion, toleratedMisses, 0, false)
578	}
579	
580	// HealthSince judges a node the same way Health does, but the missed-duty
581	// alarm is measured against a user-supplied baseline heartbeat instead of the
582	// cumulative counter alone. baselineSeq must be the seq (> 0) of a record
583	// already saved for the node: the latest heartbeat stays the record with the
584	// greatest seq, and new missed duties are the latest cumulative count minus
585	// the count at the baseline record. Only a strict excess over
586	// toleratedMisses alarms; equality does not.
587	//
588	// The baseline affects this query only: stored history is never modified.
589	// Seqs between the baseline and the latest may have gaps. If the cumulative
590	// count decreases between any two adjacent saved records in that interval the
591	// new count is reported as unknown (NewMissedKnown == false) and a rollback
592	// finding is emitted, even if the latest count later climbs back past the
593	// baseline; decreases before the baseline are irrelevant. A node without
594	// telemetry, an unknown baseline seq, or a baseline newer than the latest
595	// record is an error — no other record is substituted and the baseline count
596	// is never assumed to be zero.
597	func (s *Store) HealthSince(nodeID string, at time.Time, expectedVersion string, toleratedMisses int, baselineSeq int64) (HealthResult, error) {
598		if baselineSeq <= 0 {
599			return HealthResult{}, fmt.Errorf("--missed-since-seq must be a positive integer, got %d", baselineSeq)
600		}
601		return s.health(nodeID, at, expectedVersion, toleratedMisses, baselineSeq, true)
602	}
603	
604	func (s *Store) health(nodeID string, at time.Time, expectedVersion string, toleratedMisses int, baselineSeq int64, useBaseline bool) (HealthResult, error) {
605		unlock, err := s.lock(false)
606		if err != nil {
607			return HealthResult{}, err
608		}
609		defer unlock()
610	
611		nf, err := loadNodeFile(s.nodeLocationFor(nodeID))
612		if err != nil {
613			return HealthResult{}, err
614		}
615		if nf == nil || len(nf.Records) == 0 {
616			if useBaseline {
617				return HealthResult{}, fmt.Errorf("node %q has no heartbeats; cannot use --missed-since-seq=%d as baseline", nodeID, baselineSeq)
618			}
619			return HealthResult{NodeID: nodeID, Status: "notelemetry", Findings: []string{"无遥测"}}, nil
620		}
621	
622		records := nf.Records // ascending seq, unique
623		latest := records[len(records)-1]
624	
625		if useBaseline {
626			if baselineSeq > latest.Seq {
627				return HealthResult{}, fmt.Errorf("--missed-since-seq=%d is newer than the latest heartbeat seq %d for node %q", baselineSeq, latest.Seq, nodeID)
628			}
629		}
630	
631		if at.Before(latest.CollectedAt) {
632			return HealthResult{}, fmt.Errorf("query time %s is earlier than collection time %s for node %q",
633				at.Format(time.RFC3339), latest.CollectedAt.Format(time.RFC3339), nodeID)
634		}
635	
636		age := at.Sub(latest.CollectedAt)
637		online := age <= onlineWindow
638	
639		result := HealthResult{
640			NodeID:      nodeID,
641			Status:      "online",
642			Seq:         latest.Seq,
643			CollectedAt: latest.CollectedAt,
644			Version:     latest.Version,
645			Height:      latest.Height,
646			Missed:      latest.Missed,
647		}
648		if !online {
649			result.Status = "offline"
650		}
651	
652		if !useBaseline {
653			// Cumulative judgement: the current counter must strictly exceed the
654			// tolerance. Evaluate holds this rule — and the shared online/version
655			// rules — in exactly one place for the demo and both query paths.
656			node := Node{
657				ID:      nodeID,
658				Version: latest.Version,
659				Height:  latest.Height,
660				Missed:  int(latest.Missed),
661				Online:  online,
662			}
663			result.Findings = Evaluate(node, expectedVersion, toleratedMisses).Findings
664			return result, nil
665		}
666	
667		// Baseline judgement: the online and version-skew findings come from the
668		// same shared rules as the cumulative query above; only the missed-duty
669		// statistic differs — it counts duties missed after the baseline record
670		// instead of the latest cumulative total.
671		findings := append([]string{}, livenessVersionFindings(online, latest.Version, expectedVersion)...)
672	
673		baselineIdx := -1
674		for i, r := range records {
675			if r.Seq == baselineSeq {
676				baselineIdx = i
677				break
678			}
679		}
680		if baselineIdx < 0 {
681			return HealthResult{}, fmt.Errorf("no saved heartbeat with seq %d for node %q; cannot use it as --missed-since-seq baseline", baselineSeq, nodeID)
682		}
683		baseline := records[baselineIdx]
684		result.BaselineSeq = baseline.Seq
685		result.BaselineMissed = baseline.Missed
686	
687		// Walk only saved records from the baseline up to the latest. Records are
688		// stored ascending by seq and seqs may legitimately have gaps, so any
689		// decrease between two adjacent saved records in this interval proves the
690		// cumulative counter reset somewhere in it; the endpoint difference alone
691		// must not be trusted even if the final count recovers.
692		rolledBack := false
693		for i := baselineIdx + 1; i < len(records); i++ {
694			if records[i].Missed < records[i-1].Missed {
695				rolledBack = true
696				break
697			}
698		}
699		if rolledBack {
700			result.NewMissedKnown = false
701			findings = append(findings, rollbackFinding)
702		} else {
703			result.NewMissedKnown = true
704			// No decrease was observed, so cumulative counts cannot have wrapped
705			// backwards within int64 range; the difference stays exact.
706			result.NewMissed = latest.Missed - baseline.Missed
707			if result.NewMissed > int64(toleratedMisses) {
708				findings = append(findings, missedAboveToleranceFinding)
709			}
710		}
711		result.Findings = findings
712		return result, nil
713	}
714	
715	// History returns all heartbeats for a node in ascending seq order, without
716	// duplicates. A node with no records returns an empty slice.
717	func (s *Store) History(nodeID string) ([]Heartbeat, error) {
718		unlock, err := s.lock(false)
719		if err != nil {
720			return nil, err
721		}
722		defer unlock()
723	
724		nf, err := loadNodeFile(s.nodeLocationFor(nodeID))
725		if err != nil {
726			return nil, err
727		}
728		if nf == nil {
729			return []Heartbeat{}, nil
730		}
731		return nf.Records, nil
732	}
733

