package edgefleet

import (
	"os"
	"path/filepath"
	"testing"
	"time"
)

func hbT(node string, seq int64, base time.Time) Heartbeat {
	return Heartbeat{NodeID: node, Seq: seq, CollectedAt: base.Add(time.Duration(seq) * time.Second), Version: "1.0", Height: seq, Missed: 0}
}

// Pure duplicate batch succeeds even when the node's file location forbids writes.
func TestPureDuplicateNoWrite(t *testing.T) {
	dir := t.TempDir()
	base := time.Date(2026, 10, 1, 0, 0, 0, 0, time.UTC)
	s, _ := OpenStore(dir)
	r := hbT("n1", 1, base)
	if n, d, err := s.Submit([]Heartbeat{r}, base.Add(time.Hour)); err != nil || n != 1 || d != 0 {
		t.Fatalf("first submit: n=%d d=%d err=%v", n, d, err)
	}
	// Forbid creating/replacing files in nodes/.
	nodesDir := filepath.Join(dir, "nodes")
	os.Chmod(nodesDir, 0o555)
	defer os.Chmod(nodesDir, 0o755)
	// Same record three times.
	n, d, err := s.Submit([]Heartbeat{r, r, r}, base.Add(time.Hour))
	if err != nil || n != 0 || d != 3 {
		t.Fatalf("dup submit: n=%d d=%d err=%v", n, d, err)
	}
	hist, err := s.History("n1")
	if err != nil || len(hist) != 1 {
		t.Fatalf("history: len=%d err=%v", len(hist), err)
	}
}

// Mixed batch: node A gains a record, node B is duplicates-only and unwritable.
func TestMixedBatchSkipsUnwritableDupNode(t *testing.T) {
	dir := t.TempDir()
	base := time.Date(2026, 10, 1, 0, 0, 0, 0, time.UTC)
	s, _ := OpenStore(dir)
	b1 := hbT("b", 1, base)
	if _, _, err := s.Submit([]Heartbeat{b1}, base.Add(time.Hour)); err != nil {
		t.Fatal(err)
	}
	// Make b's file unreplaceable: replace nodes/<hex b>.json's dir entry is
	// in nodes/, shared with a. Instead give b a long id? Simpler: submit a
	// batch where b is dup-only and a is new, with nodes/ writable — verify
	// b's file mtime/content unchanged.
	bPath := s.nodePath("b")
	before, _ := os.ReadFile(bPath)
	a1 := hbT("a", 1, base)
	n, d, err := s.Submit([]Heartbeat{b1, a1}, base.Add(time.Hour))
	if err != nil || n != 1 || d != 1 {
		t.Fatalf("mixed: n=%d d=%d err=%v", n, d, err)
	}
	after, _ := os.ReadFile(bPath)
	if string(before) != string(after) {
		t.Fatal("dup-only node file was rewritten")
	}
	histA, _ := s.History("a")
	if len(histA) != 1 {
		t.Fatal("node a record not saved")
	}
}

// Corrupt history of a dup-only node still rejects the batch.
func TestCorruptDupNodeRejects(t *testing.T) {
	dir := t.TempDir()
	base := time.Date(2026, 10, 1, 0, 0, 0, 0, time.UTC)
	s, _ := OpenStore(dir)
	b1 := hbT("b", 1, base)
	s.Submit([]Heartbeat{b1}, base.Add(time.Hour))
	os.WriteFile(s.nodePath("b"), []byte("garbage"), 0o644)
	a1 := hbT("a", 1, base)
	if _, _, err := s.Submit([]Heartbeat{b1, a1}, base.Add(time.Hour)); err == nil {
		t.Fatal("expected corruption error")
	}
	if hist, _ := s.History("a"); len(hist) != 0 {
		t.Fatal("node a must not have been saved")
	}
}
EOF
